) AS v("handle", "award", "year", "position", "title", "source_url")
JOIN "public"."profiles" p ON p.handle = v.handle AND p.kind = 'bar'
-- An award already there under another spelling ("Best New Opening Award",
-- "The Best Bar in Japan") keeps its row.
WHERE NOT EXISTS (
    SELECT 1 FROM "public"."profile_awards" b
    WHERE b.profile_id = p.id AND b.award = v.award AND b.year = v.year::smallint AND v.title IS NOT NULL
      AND lower(regexp_replace(regexp_replace(b.title, ' Award$', ''), '^The ', ''))
        = lower(regexp_replace(regexp_replace(v.title, ' Award$', ''), '^The ', ''))
)
-- Rows already there with the same wording are kept too.
ON CONFLICT DO NOTHING;

INSERT INTO "public"."profile_menu_editions" ("profile_id", "name", "year", "month", "theme", "drinks", "source_url")
SELECT p.id, v.name, v.year::smallint, v.month::smallint, v.theme, v.drinks, v.source_url
FROM (VALUES
    ('frontbackaccra', 'FB Menu Book 2024', 2024, 4, 'Pan-African signature list named for Ghanaian places and words, using local produce like apio, moringa, sobolo and cocoa.', ARRAY['Jamestown', 'Akwasi', 'Asaase', 'Ny Aniba', 'Atadika', 'Owura', 'Emefa', 'Demosthene', 'Ajabu', 'Oxford Street Sour', 'Café Negroni', 'My-Tea-Ni', 'Sorrel Sangria']::text[], 'https://uploads-ssl.webflow.com/60a676b012dee37145d9e5f1/661eb74ffe3c6514060bf3a6_FB%20MENU%20BOOK%202024.pdf'),
    ('flyingdutchmencocktails', 'Walk Run Fly: opening Evolution menu', 2017, 12, 'Classics-led list tracing the evolution of genever, champagne, daiquiri, New Orleans, aperitivo and fizz drinks, plus a few house signatures.', ARRAY['Collins', 'Blue Devil Cocktail', 'Flying Dutchmen Cocktail', 'French 75', 'Bernice Royale', 'Seelbach', 'Daiquiri', 'Santa Marta', 'Dutch Daiquiri', 'Brandy Crusta', 'Vieux Carre', 'Hurricane', 'Milano-Torino', 'Negroni', 'White Mezcal Negroni', 'Morning Glory Fizz', 'Sloe Gin Fizz', 'Irish Royal Fizz']::text[], 'http://web.archive.org/web/20180508124050/http://www.flyingdutchmencocktails.com:80/menu.pdf'),
    ('flyingdutchmencocktails', 'Evolution menu (2019)', 2019, 9, 'Six sections each showing a classic, an advanced variation and a house twist: genever, crème de cassis, falernum, fruit preserves, Japan and the Last Word.', ARRAY['The Bird is The Word #1', 'Royal Bermuda Yacht Club', 'Japanese Cocktail', 'Jack the Ripper', 'Flying Dutchman Cocktail', 'Apricot Cosmo', 'Three Dots and a Dash', 'Japanese Slipper', 'La Ninja']::text[], 'https://www.thespiritsbusiness.com/2019/09/flying-dutchmen-menu-highlights-cocktail-evolution/'),
    ('flyingdutchmencocktails', 'Menu 2026', 2026, 5, 'Evolution format continues with punch, Margarita relatives, pomegranate-syrup modifiers and Bee''s Knees families alongside the house signature.', ARRAY['Flying Dutchmen Cocktail', 'OG Punch', 'British Milk Punch', 'FlyFish House Punch', 'Picante', 'Pink Chihuahua', 'Umami Margarita', 'El Presidente', 'Scofflaw', 'Piccadilly Martini', 'Bee''s Knees', 'Lavender Honey Sour']::text[], 'https://irp.cdn-website.com/e2819987/files/uploaded/correct+-+flyingdutchmen_kaart_2026_140526.pdf'),
    ('barronegroathens', 'Hecho en México cocktail list', 2026, NULL, 'Agave-only signatures that keep tequila or mezcal as the hero, alongside Mexican-style serves and house favourites like the Paloma.', ARRAY['Para Todo Bien', 'Mayans'' Punch', 'Birria Martini', 'Los Abuelos', 'Cenote', 'Lokalism', 'Papalote', 'Mezcal & Tonic', 'Strawberry Luna', 'Amarillo']::text[], 'https://www.barronegroathens.com/menu'),
    ('naked.athens', 'Mixed Drinks and Booze (menu v4.2)', 2023, 10, 'Cheeky, nudity-themed twists on popular drinks built with Greek ingredients such as mastiha, Metaxa and bergamot.', ARRAY['Porn AF', 'Still Cosmo', 'Bare Havaiana', 'Nude Mai Tai', 'Sexy Gimlet', 'Wanna Make You Sweat', 'Smoke After Pleasure', 'Naked Nipples', 'Sex on the Peach']::text[], 'https://nakedbarathens.com/wp-content/uploads/2024/01/menu_cocktails-v4.2_compressed.pdf'),
    ('naked.athens', 'Discover the Uncovered', 2025, 10, 'Pairs ''uncovered'' and ''discovered'' takes on familiar drinks, revealing raw natural ingredients with new techniques and a zero-waste approach.', ARRAY['Pink Grapefruit Tequila Sunrise', 'Spicy Mango Paloma', 'Pornstar Maracuja', 'Strawberry Bloody Mary', 'Kiwi G&T', 'Apple #Not Martini', 'Pineapple Tai', 'NKD-aiquiri Banana', 'Scotch & #Not Soda', 'Carob Old Fashioned']::text[], 'https://nakedbarathens.com/wp-content/uploads/2026/09/NKD-ATH-COCKTAIL-MENU.pdf'),
    ('the_clumsies', 'S=mc3', 2016, 5, 'Menu built on the theory of relativity, reimagining classics with fermentation and modern technique, from a futuristic whisky-cola to a mushroom drink.', ARRAY['El Draque', 'The Shakers Boy', 'Infinity', 'Unknown Pleasures', 'Umami Clay', 'Jenna Sain']::text[], 'https://www.diffordsguide.com/encyclopedia/1117/bars/the-clumsies-new-cocktail-menu'),
    ('the_clumsies', 'Happy Accidents', 2023, 7, 'Fourteen cocktails built around everyday happy accidents, using fermentation and unusual pairings like cheddar with tangerine.', ARRAY['Catching a Falling Star', 'Forgetting the Umbrella', 'Missing the Train', 'Finding a Treasure']::text[], 'https://drinksint.com/menu-of-the-month-happy-accidents-by-the-clumsies/'),
    ('the_clumsies', 'Spirits of the City: Polykatoikia', 2026, 5, 'Each cocktail portrays an Athenian creative (architect, street artist, writer, comic artist) through the lens of the city''s apartment blocks.', ARRAY['City Skin', 'Spirit of the City', 'The Pause Between', 'YesterNow', 'Kykeon', 'Rec & Play', 'Changing Seasons', 'Perfect Imperfection', 'Proika', 'Curated Chaos']::text[], 'https://www.theclumsies.gr/catalogue/clumsies-cocktail-menu-2023.pdf?v=8'),
    ('americanbargleneagles', 'Book of Berries', 2023, 12, 'Styled on pocket Observer''s Books, each drink is an illustrated ode to a berry or plant, with a flavour map and technique footnotes.', ARRAY['Juniper', 'Aubergine', 'Kiwi', 'Blueberry']::text[], 'https://drinksint.com/menu-of-the-month-the-american-bar-at-gleneagles-hotel/'),
    ('americanbargleneagles', 'Rose Compendium', 2025, 2, 'Nineteen serves inspired by a 1925 Rose Annual, each drawn from the rose family and shown in two terroir-driven versions.', ARRAY['The Orchard Sap', 'Amber Stem', 'Smoked Cherry', 'Spiced Marzipan']::text[], 'https://www.thespiritsbusiness.com/2025/02/gleneagles-american-bar-spotlights-roses-in-new-menu/'),
    ('opm.bkk', 'Liquid Surreality (Summer 2022)', 2022, 6, 'Opening-era list sorted into six ''liquid'' categories (aperitif, sparkle, acid, acid+, solo, duo) with everything made in-house.', '{}'::text[], 'https://www.opiumbarbangkok.com/s/Opium-Menu-2022-Summer-PDF.pdf'),
    ('opm.bkk', 'Expression Cocktails', 2024, 10, 'First edition of drinks that each capture a specific place (a mangrove canal, Isan sugarcane fields, Oaxaca) through local makers and ingredients.', '{}'::text[], 'https://www.opiumbarbangkok.com/s/Opium-Menu-2024.pdf'),
    ('opm.bkk', 'Expression Cocktails #2', 2025, 12, 'Second edition of place-driven drinks capturing moments from Thailand, Vietnam and Italy, plus the team''s competition-winning cocktails.', ARRAY['Mid Summer', 'Jamming James', 'La Diablada', 'Song Wat', 'Inseparable', 'Juxtaposed', 'Twilight Alley', 'Reverie in Yellow', 'Fig & Fog', 'Campfire', 'Echoes', 'First Blush', 'Dot Dot Dot', 'Dee Dee Da Da Dah', 'Salted Winter', 'Fifth Moon', 'Pleasure Spiked', 'Ember', 'Drinking in Color', 'With Pain']::text[], 'https://www.opiumbarbangkok.com/s/Opium-Menu-2026-PDF.pdf'),
    ('rabbitholebkk', 'The Rabbit Hole of Emotions', 2026, 7, 'Four acts (Surface, Descent, Reflection, Ascension) with each drink named for an emotion and built on Thai ingredients.', ARRAY['Laughter (55555)', 'Love', 'Loneliness', 'Tickled', 'Curiosity', 'Regret', 'Fear', 'Anger', 'Peace', 'Desire', 'Confusion', 'Relief', 'Nostalgia', 'Addiction', 'Clarity', 'Resilience']::text[], 'https://rabbitholebkk.com/s/20260713_RH_MenuSignature_DoublePage.pdf'),
