    ('vesperbkk', 'Opening menu', 2014, NULL, 'First list at opening, developed with London consultants Thomas Aske and Tristan Stephenson in a European cocktail-bar style.', '{}'::text[], 'https://drinksint.com/bar-guide-bangkok/'),
    ('vesperbkk', 'Britain Through Seasons', 2026, 6, 'A tribute to Britain across spring, summer, autumn and winter, each drink framed as a ''kind of'' familiar classic.', ARRAY['Shandy Shake', 'Rhubarb & Cream', 'Beesting', 'Parakeet', 'Solero', 'Session Bitter', 'Golden Brown', 'Leaf & Soil', 'Roots', 'Preserves', 'Baked Apple', 'Forest Walk']::text[], 'https://www.vesperbar.co/_files/ugd/a7e7ff_ebd0ec311fa44849b545a30d2ab0f375.pdf'),
