    ('two.schmucks', 'Flavour of Schmucks', 2021, 11, 'First list from creative directors Juliette Larrouy and Pom Modeste, savoury drinks drawn from dishes with personal meaning to the team.', ARRAY['Melon, Cheese & Pepper', 'Granny Punch', 'Tom Kha', 'Tartines', 'French Soup Manhattan']::text[], 'https://www.thespiritsbusiness.com/2021/11/two-schmucks-new-cocktail-menu-goes-savoury/'),
    ('antiqueamericanbar_bratislava', 'Taste of Art (6th edition)', 2025, 6, 'Sixth menu edition, each drink named for an artist and built from three adjectives describing one of nine art movements from Renaissance to Pop Art.', ARRAY['Leonardo da Vinci', 'Michelangelo', 'Antonio Canova']::text[], 'https://www.antique-americanbar.com/_files/ugd/bdf7ff_f4bfb0bee07243beb241f877082c13c9.pdf'),
    ('floreriaatlantico', 'Colonies and Original Towns', 2026, NULL, 'Drinks honouring Argentina''s native peoples and immigrant colonies, using regional spirits and ingredients like coca leaf, carob and calafate.', ARRAY['Ofrenda', 'Coya Raymi', 'Pachay', 'Agua del Sol', 'Yvy Maraey', 'Monte Arriba', 'Karu Hára', 'Wenu', 'Patagones', 'Pehuén', 'El Último Pueblo', 'Colonia Luján', 'Ostende', 'Gente del Este']::text[], 'https://www.floreriaatlantico.com.ar/menues/FA_tragos%20y%20bebidas-doblep-eng.pdf'),
    ('causeeffectcpt', 'Tastebuds and Molecules', 2018, 9, 'Science-of-taste list using local raw ingredients, aroma-paired vintage classics and four alcohol-free Noble Experiments.', ARRAY['State of Mind', 'Avo-Ntitious', 'Rooibos Brandy Sour', 'Cape Sugar Bird', 'Richie the Rainbow Sparkle Unicorn', 'Membrane', 'Noix de Coco et Poire']::text[], 'https://www.thespiritsbusiness.com/2018/09/cause-effect-menu-highlights-the-science-of-taste/'),
    ('lab22cardiff', 'Discovery & Progress', 2017, 8, 'First of a science trilogy, putting the lab theme into the drinks and the menu itself rather than just beaker glassware.', '{}'::text[], 'https://www.lab22cardiff.com/discovery-progress/'),
    ('lab22cardiff', 'Pioneers + Revolutionaries', 2019, 7, 'Homage to scientists of the past, split equally between men and women, from Archimedes and Newton to Rosalind Franklin and Ada Lovelace.', '{}'::text[], 'https://drinksint.com/we-never-thought-wed-actually-win-it-lab-22s-max-hayward-on-having-the-worlds-best-cocktail-menu/'),
    ('lab22cardiff', 'Theories + Frontiers', 2020, 9, 'Last of the science trilogy, on unexplored science like black holes, deep space and venomics; won 50 Best''s first Best Cocktail Menu award.', ARRAY['Voyager']::text[], 'https://drinksint.com/we-never-thought-wed-actually-win-it-lab-22s-max-hayward-on-having-the-worlds-best-cocktail-menu/'),
    ('lab22cardiff', 'ACT', 2025, 2, 'Built on accessibility, community and transparency, every drink is a collaboration with a local South Wales business, from beekeepers to potters.', ARRAY['The Grapes of Taff', 'Samba!', 'This is a Strobbery', 'Apiculture Club', 'Core Principle', 'Aunt Lucy''s Advice', 'Peach Perfect', 'Garden Margarita', 'Raspberry 3.14', 'Green Light', 'Finders Keepers', 'Wild West', 'Paradise Citadel', 'Cwtch Me if You Can', 'Claymaker']::text[], 'https://www.lab22cardiff.com/drinks/'),
    ('elbaroncafe', 'Signature Cocktails & Food Menu (Sept 2026)', 2026, 9, 'Seasonal and timeless signatures built on Colombian ingredients like viche, lulo-style fruits and local botanicals, tagged by profile and technique.', ARRAY['Runas Marinas', 'Blume', 'Yang Long', 'Alacran', 'Aurora', 'Cucumis Sour No. 2', 'Rosarito', 'Veranera', 'Mojito Providencia']::text[], 'https://www.elbaron.co/s/BAR260907menu-cocktails-food-ing-op.pdf'),
