    ('theotherroomsg', 'Cocktail menu (cask-finished house list)', 2024, 7, 'House list built on the bar''s own cask-finished spirits, mixing classics with twists, sangria punches and tea-infused signatures.', ARRAY['Flamenco Martini', 'Trouble in Paradise', 'La Boheme', 'Reversed Gin & Tonic', 'Royal Mojito', 'Teaspresso Martini', 'Monkey See Monkey Do', 'White Punch', 'Red Punch']::text[], 'https://www.theotherroom.com.sg/_files/ugd/e8a37a_f9e55f9978d54be998009698b9bc28fb.pdf'),
    ('lucysstockholm', 'Opening menu', 2019, 11, 'Minimalist embossed card of nine centrifuge-driven signatures, simple in look but technical in build.', ARRAY['Sichuan & Peach IPA']::text[], 'https://www.diffordsguide.com/bars/J7OnAz/lucys-flower-shop'),
    ('tjoget', 'Hedda Bruce menu (DI Menu of the Month)', 2024, 10, 'Team-built list of classic twists with Mediterranean, North African and Middle Eastern flavours, led by bar manager Hedda Bruce.', ARRAY['Polo Lounge Martini', 'Piccadilly Circus', 'Berry Bonds', 'Beets']::text[], 'https://drinksint.com/menu-of-the-month-tjoget/'),
    ('tjoget', 'Seasonal cocktails (summer list)', 2026, NULL, 'Summer seasonal list of fruit-led aperitivo twists shown beside the house Tjoget Classics.', ARRAY['Sash Bamboo', 'Supersonic', 'Hot Hot Summer', 'Graceland', 'Tequila Gimlet', 'Kentucky Rosa', 'Mango Garibaldi', 'Ticket to Capri']::text[], 'https://tjoget.com/'),
    ('thelobo_syd', 'Twentieth Edition', 2023, 11, 'Rum-bar list in the bar''s Julio Lobo story format, with regional rum flights and house drinks such as the stout-vermouth Old Grogram.', '{}'::text[], 'https://www.thelobo.com.au/s/The-Lobo-20th-Cocktail-List-compressed.pdf'),
    ('thelobo_syd', 'Twenty First Edition', 2025, 2, 'New edition of the house cocktail list alongside rum flights, including a Tiki section and a rotating speciality.', '{}'::text[], 'https://www.thelobo.com.au/s/Lobo_Cocktail-Menu-2025-website_compressed-2te5.pdf'),
    ('thelobo_syd', 'Twenty Second Edition', 2025, 9, 'Reorganised around the Daiquiri, with a Daiquiri list, Friends of Daiquiris and Not a Daiquiri; pandan brief behind Blend 130.', ARRAY['Blend 130']::text[], 'https://www.thelobo.com.au/s/LOBO_MENU__080925_WEBSITE_1908.pdf'),
    ('thelobo_syd', 'Twenty Third Edition', 2026, 9, 'Latest list of daiquiris, signatures and limited editions, plus a featured rums section.', ARRAY['Bacardi Daiquiri', 'Aged Blend Daiquiri', 'Nuclear Daiquiri', 'Dry Daiquiri', 'Royal Bermuda Yacht Club']::text[], 'https://www.thelobo.com.au/s/SeptemberWebsiteMenu.pdf'),
    ('disco_pantera', 'Opening menu', 2024, 9, 'Disco Pantera''s seasonal-produce cocktails with a 1970s New York disco spirit, alongside Tigra''s aperitif bar downstairs.', ARRAY['Chimichurri Margarita', 'Alpine Sazerac', 'Cleopatra Martini', 'Pantera Creaming Soda']::text[], 'https://australianbartender.com.au/2024/09/19/the-purnell-brothers-open-disco-pantera-tigra-open-in-sydneys-cbd/'),
    ('indulgebistro', 'Before x After (2017 Chef''s Menu)', 2017, 5, 'Cocktail-and-dish pairings mapped onto Taiwan''s regions, North, South and East, mixing classic elements with local terroir.', ARRAY['Sakura Blossom']::text[], 'https://indulgebistrotaipei.blogspot.com/2017/05/before-x-after-x-east.html'),
    ('indulgebistro', 'Tales of Taiwan (2018/19 drinks list)', 2018, 7, 'New drinks list reinterpreting Taiwan''s local flavours with a sustainability focus, paired with a region-by-region food menu.', '{}'::text[], 'https://indulgebistrotaipei.blogspot.com/2018/07/2018-indulge-bistro-tales-of-taiwan.html'),
    ('indulgebistro', '2020 drinks list: Metal, Wood, Water, Fire, Earth', 2020, 5, 'New 2020 cocktail list organised around the five elements of Chinese philosophy.', '{}'::text[], 'https://indulgebistrotaipei.blogspot.com/2020/09/2020-indulge.html'),
    ('bellboy.tlv', '15th Tel Aviv Edition', 2026, 7, 'Playful signatures grouped by flavour (Fruity, Refreshing, Sour and more) with theatrical garnishes and house blends.', ARRAY['Breakwater', 'Night @ 54', 'Viking Club', 'Zanzibar', 'A Lesson in Fisting', 'Keep Clean #3', 'Last Samurai', 'Ocean''s Eight', 'Rings a Bell', 'Greengo', 'Hemingway Daiquiri #14', 'Why The Sour Face?']::text[], 'https://bellboygroup.com/wp-content/uploads/2026/09/Bellboy-TLV-Drink-Menu-July-2026.pdf'),
    ('barhighfive', 'Bartenders'' Choice house list', 2020, 8, 'Standing list of house specials, Kaory''s painting-inspired drinks and Japanese old classics, beside seasonal fruit cocktails.', ARRAY['Ceremony', 'Japanese Garden', 'Harvester', 'Full Bloom', 'Curtain Call', 'Sanshin Premium', 'Awl (Pink Gimlet)', 'Innocent Love', 'Huntsman', 'Les Tournesols', 'L''Angelus', 'Noa Noa', 'Composition']::text[], 'https://web.archive.org/web/20200808053213/https://www.barhighfive.com/menu'),
    ('bar_trench', 'Autumn 2012 menu', 2012, NULL, 'Seasonal autumn list posted as an image on the old Bar Trench site; drinks not readable.', '{}'::text[], 'https://web.archive.org/web/20121127191111/http://small-axe.net/bar-trench/menu.html'),
    ('bargenyamamoto', 'Omakase seasonal cocktail course', 2013, NULL, 'Course-style omakase of four to seven cocktails built from seasonal Japanese produce, reflecting shiki (the seasons).', '{}'::text[], 'http://www.genyamamoto.jp/'),
    ('bar_raval', 'Cocktail list (2019)', 2019, 7, 'House cocktails leaning on sherry, house-made akvavit and amaro, alongside a Raval Spanish Coffee.', ARRAY['Into The Sun', 'Palm Springs Pawn Shop', 'Raval Spanish Coffee', 'Demiana', 'The Walk Off', 'Malibu Barbie', 'Lake of Fire']::text[], 'https://web.archive.org/web/20190722232831/https://www.thisisbarraval.com/drinks'),
    ('bar_raval', 'Cocktail list (2022)', 2022, 7, 'New house list built on vermouth, sherry and savoury infusions, with a Raval Martini.', ARRAY['¡Santa Maria!', 'Say Less', 'Magic City', 'Under The Bridge', 'See U Never', 'The Norman Foster', 'Unlovable', 'Raval Martini']::text[], 'https://web.archive.org/web/20220702231204/https://www.thisisbarraval.com/drinks'),
    ('bar_raval', 'Flavour-grouped list (2025)', 2025, 3, 'List reorganised by style, such as Citrusy & Refreshing and Stirred & Strong, with house highballs.', ARRAY['Disco Paradiso', 'French & Pretty', 'Juna', '5 Points', 'Sundowner', 'Tropic of Capricorn', 'Palomino Club', 'A Fancy Margarita', 'SLC Punch', 'Shorter Poems']::text[], 'https://web.archive.org/web/20250327064413/https://www.thisisbarraval.com/drinks'),
    ('bar_raval', 'Signature cocktails (2026)', 2026, 1, 'Signatures built on clarified punches and fat-washed spirits, plus highballs, classics and non-alcoholic serves.', ARRAY['Porcelain Electric', 'Fancy Margarita', 'Tropic of Capricorn', 'Lady Jang', 'May December', 'SLC Punch!', 'Shelly in Athens', 'Radio Pornella']::text[], 'https://web.archive.org/web/20260112202502/https://www.thisisbarraval.com/drinks'),
    ('arcatulum', 'House cocktails (2016)', 2016, 3, 'Early house list of agave, rum and gin drinks with local honey and wood-fired pineapple, plus classics.', ARRAY['Hemingüey', 'El Solar', 'Lone Palm', 'Chechén', 'Har Mar Superstar', 'The VK', 'La Doña', 'Machin Pichu']::text[], 'https://web.archive.org/web/20160311123407/http://arcatulum.com/cocktail-menus'),
    ('arcatulum', 'House cocktails (2021)', 2021, 10, 'Reworked house list adding sotol, xtabentún and chapulín-salt drinks while keeping some opening signatures.', ARRAY['Har Mar Superstar', 'Naked in the Desert', 'Mayami Nice', 'Oliver Twist', 'Chechén', 'El Solar', 'Lone Palm']::text[], 'https://web.archive.org/web/20211026020139/https://arcatulum.com/cocktails/'),
    ('arcatulum', 'Ciclos', 2026, NULL, 'Signature list following a plant''s life from seed to fruit, in Seeds, Leaves, Flowers and Fruits sections using Mayan jungle ingredients.', ARRAY['Bloody Mayan', 'Marzipan Carajillo', 'Pixtle Mai Tai', 'Cacao Boulevardier', 'Mayan Fizz', 'Botanical', 'Green Garden', 'Holy Last Word', 'Bees and Pollen', 'Gin Mile', 'Junglepolitan']::text[], 'https://arcatulum.com/menu')
) AS v("handle", "name", "year", "month", "theme", "drinks", "source_url")
JOIN "public"."profiles" p ON p.handle = v.handle AND p.kind = 'bar'
